import asyncio
from llama_index.core.workflow import Context, Event, StartEvent, StopEvent, Workflow, step

class DraftEvent(Event):
    text: str
class RetryEvent(Event): pass
class SloganFlow(Workflow):
    @step
    async def write(self, ctx: Context, ev: StartEvent | RetryEvent) -> DraftEvent:
        tries = await ctx.store.get("tries", default=0) + 1
        await ctx.store.set("tries", tries)
        product = ev.get("product") or await ctx.store.get("product")
        await ctx.store.set("product", product)
        # In real code: await llm.acomplete(...)
        return DraftEvent(text=f"{product}: try #{tries}" + ("!" if tries > 1 else ""))

    @step
    async def check(self, ctx: Context, ev: DraftEvent) -> RetryEvent | StopEvent:
        if not ev.text.endswith("!") and await ctx.store.get("tries") < 3:
            return RetryEvent()                       # loop back to write
        return StopEvent(result=ev.text)

async def main():
    print(await SloganFlow(timeout=30).run(product="SunMug"))   # SunMug: try #2!
asyncio.run(main())

from llama_index.core import Document, VectorStoreIndex
from llama_index.core.instrumentation import get_dispatcher
from llama_index.core.instrumentation.event_handlers import BaseEventHandler
from llama_index.core.instrumentation.events.llm import LLMChatEndEvent, LLMCompletionEndEvent
from llama_index.core.instrumentation.events.retrieval import RetrievalEndEvent

class TraceLogger(BaseEventHandler):
    @classmethod
    def class_name(cls) -> str:
        return "TraceLogger"

    def handle(self, event, **kwargs):
        if isinstance(event, RetrievalEndEvent):
            print("[retrieval]", [n.node.node_id[:8] for n in event.nodes])
        elif isinstance(event, (LLMChatEndEvent, LLMCompletionEndEvent)):
            print("[llm] done:", type(event).__name__)

get_dispatcher().add_event_handler(TraceLogger())   # root dispatcher sees everything

index = VectorStoreIndex.from_documents([Document(text="Refunds take 5 days.")])
index.as_query_engine().query("Refund time?")
# [retrieval] ['3f2a9c1b']
# [llm] done: LLMChatEndEvent
